package com.example.rokidkeyboardbridge;
import android.content.*;import android.media.*;import android.app.*;import android.widget.*;import org.json.*;
/** Explicit opt-in, device-local stream control. Never sends media keys or requests audio focus. */
final class DeviceTuning {
 static String mode="";static int baseline=-1,applied=-1,beforeSpecial=-1;static boolean overridden;static int beforeMeeting=-1;static String meetingReturn="";static String config="";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("device_tuning",0);}
 interface Volume {int get();int max();boolean fixed();void set(int value);}
 static Volume volume(Context c){AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);return new Volume(){public int get(){return a.getStreamVolume(AudioManager.STREAM_MUSIC);}public int max(){return a.getStreamMaxVolume(AudioManager.STREAM_MUSIC);}public boolean fixed(){return a==null||a.isVolumeFixed();}public void set(int value){a.setStreamVolume(AudioManager.STREAM_MUSIC,value,0);}};}
 static boolean recovered;
 static void tick(Context c,boolean meeting,boolean navigation){if(!prefs(c).getBoolean("enabled",false)&&baseline<0&&!c.getSharedPreferences("volume_lease",0).contains("original"))return;tick(c,meeting,navigation,volume(c));}
 static synchronized void tick(Context c,boolean meeting,boolean navigation,Volume audio){try{if(audio.fixed())return;SharedPreferences lease=c.getSharedPreferences("volume_lease",0);if(!recovered){if(lease.contains("original")&&audio.get()==lease.getInt("applied",-1))audio.set(lease.getInt("original",audio.get()));lease.edit().clear().commit();recovered=true;}SharedPreferences p=prefs(c);if(!p.getBoolean("enabled",false)&&baseline<0)return;String signature=p.getBoolean("enabled",false)+":"+p.getInt("normal",50)+":"+p.getInt("navigation",65)+":"+p.getInt("meeting",15);int current=audio.get();String next=VolumeProfilePolicy.mode(meeting,navigation);if(!signature.equals(config)){restore(c,audio);current=audio.get();config=signature;mode="";baseline=-1;overridden=false;}if(!p.getBoolean("enabled",false))return;if(baseline<0)baseline=current;if(applied>=0&&current!=applied){overridden=true;baseline=current;}if(next.equals(mode))return;if(!next.equals("normal")&&mode.equals("normal"))beforeSpecial=current;if(next.equals("meeting")&&!mode.equals("meeting")){beforeMeeting=current;meetingReturn=mode;}int target=next.equals("normal")&&beforeSpecial>=0?beforeSpecial:VolumeProfilePolicy.level(p.getInt(next,next.equals("normal")?50:next.equals("navigation")?65:15),audio.max());if(mode.equals("meeting")&&next.equals(meetingReturn)&&beforeMeeting>=0)target=beforeMeeting;if((next.equals("normal")||mode.equals("meeting"))&&overridden){mode=next;applied=-1;beforeSpecial=-1;lease.edit().clear().commit();return;}if(!lease.edit().putInt("original",baseline).putInt("applied",target).commit())return;audio.set(target);applied=audio.get();lease.edit().putInt("applied",applied).commit();mode=next;overridden=false;if(next.equals("normal"))beforeSpecial=-1;}catch(Exception ignored){}}
 static synchronized void restore(Context c){if(baseline<0)return;restore(c,volume(c));}
 static synchronized void restore(Context c,Volume audio){try{if(baseline>=0&&applied>=0&&VolumeProfilePolicy.mayRestore(audio.get(),applied))audio.set(baseline);c.getSharedPreferences("volume_lease",0).edit().clear().commit();}catch(Exception ignored){}baseline=-1;applied=-1;beforeSpecial=-1;mode="";overridden=false;beforeMeeting=-1;meetingReturn="";}
 static void show(Activity host,Runnable changed){SharedPreferences p=prefs(host);LinearLayout body=new LinearLayout(host);body.setOrientation(1);body.setPadding(22,12,22,12);TextView note=new TextView(host);note.setText("この端末だけのメディア音量です。Bluetoothなど同じ出力の音量にも影響します。再生・停止は操作しません。会議を優先し、終了後は直前の通常音量へ戻します。手動変更した音量は上書きして戻しません。");body.addView(note);CheckBox enabled=new CheckBox(host);enabled.setText("状況別の音量を自動変更（初期OFF）");enabled.setChecked(p.getBoolean("enabled",false));body.addView(enabled);String[] keys={"normal","navigation","meeting"},names={"通常","ナビ","会議"};int[] defaults={50,65,15};SeekBar[] sliders=new SeekBar[3];for(int i=0;i<3;i++){TextView label=new TextView(host);body.addView(label);SeekBar slider=new SeekBar(host);slider.setMax(100);slider.setProgress(p.getInt(keys[i],defaults[i]));label.setText(names[i]+" "+slider.getProgress()+"%");final String name=names[i];slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int value,boolean user){label.setText(name+" "+value+"%");}});body.addView(slider);sliders[i]=slider;}CheckBox adaptive=new CheckBox(host);adaptive.setText("電池・発熱に合わせて任意の画像処理を調整");adaptive.setChecked(p.getBoolean("adaptive",true));boolean supportsAdaptive=host.getPackageName().equals("com.example.rokidkeyboardbridge");if(supportsAdaptive)body.addView(adaptive);Button undo=new LokiActionButton(host);undo.setText("直前の対応設定に戻す");undo.setOnClickListener(v->new LokiAlertDialogBuilder(host).setMessage("最後に変更した音量・負荷設定、または対応する表示設定を戻しますか？").setPositiveButton("戻す",(d,w)->{try{restore(host);String result=SettingsJournal.undo(host);changed.run();new LokiAlertDialogBuilder(host).setMessage(result).setPositiveButton("閉じる",null).show();}catch(Exception e){Toast.makeText(host,"設定を戻せませんでした",Toast.LENGTH_LONG).show();}}).setNegativeButton("やめる",null).show());body.addView(undo);ScrollView scroll=new ScrollView(host);scroll.addView(body);new LokiAlertDialogBuilder(host).setTitle("端末の音量・負荷・設定取り消し").setView(scroll).setPositiveButton("保存",(d,w)->{try{JSONObject edits=new JSONObject().put("enabled",enabled.isChecked());if(supportsAdaptive)edits.put("adaptive",adaptive.isChecked());for(int i=0;i<3;i++)edits.put(keys[i],sliders[i].getProgress());SettingsJournal.change(host,"device_tuning",edits);restore(host);changed.run();}catch(Exception e){Toast.makeText(host,"設定を保存できませんでした",Toast.LENGTH_LONG).show();}}).setNegativeButton("閉じる",null).show();}
 private DeviceTuning(){}
}
